from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject


class NTPSettings(SchemaObject):
    ntp_server_domain = SchemaField(name="ntpServerDomain")
    ntp_servers = SchemaField(name="ntpServers")
    time_zone = SchemaField(name="timeZone")

    def __init__(self, ntp_server_domain, ntp_servers, time_zone):
        self.ntp_server_domain = ntp_server_domain
        self.ntp_servers = ntp_servers
        self.time_zone = time_zone

        super(NTPSettings, self).__init__()
